CREATE TABLE "public"."auth_tenant"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),name text NOT NULL UNIQUE,status text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,row_version bigint NOT NULL DEFAULT 0);
CREATE TABLE "public"."auth_user"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),email varchar(254) NOT NULL,username text,display_name text,status text NOT NULL,email_verified_at bigint,last_login_at bigint,created_at bigint NOT NULL,updated_at bigint NOT NULL,deleted_at bigint,row_version bigint NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX "auth_user_email_live" ON "public"."auth_user"(tenant_id,email) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX "auth_user_username_live" ON "public"."auth_user"(tenant_id,username) WHERE username IS NOT NULL AND deleted_at IS NULL;
CREATE TABLE "public"."auth_password"(user_id bytea PRIMARY KEY REFERENCES "public"."auth_user"(id),password_hash text NOT NULL,algorithm text NOT NULL,parameters text NOT NULL,failed_attempts bigint NOT NULL DEFAULT 0,locked_until bigint,password_changed_at bigint NOT NULL,row_version bigint NOT NULL DEFAULT 0);
CREATE TABLE "public"."auth_session"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),user_id bytea NOT NULL REFERENCES "public"."auth_user"(id),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),token_digest bytea NOT NULL UNIQUE,expires_at bigint NOT NULL,revoked_at bigint,rotated_from_id bytea REFERENCES "public"."auth_session"(id),created_at bigint NOT NULL,last_seen_at bigint);
CREATE TABLE "public"."auth_one_time"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),user_id bytea NOT NULL REFERENCES "public"."auth_user"(id),purpose text NOT NULL,token_digest bytea NOT NULL,expires_at bigint NOT NULL,consumed_at bigint,attempt_count bigint NOT NULL DEFAULT 0,created_at bigint NOT NULL,UNIQUE(purpose,token_digest));
CREATE TABLE "public"."auth_api_key"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),user_id bytea REFERENCES "public"."auth_user"(id),service_account_id bytea,name text NOT NULL,prefix text NOT NULL,secret_digest bytea NOT NULL UNIQUE,scopes text NOT NULL,expires_at bigint,revoked_at bigint,last_used_at bigint,created_at bigint NOT NULL,CHECK((user_id IS NULL) <> (service_account_id IS NULL)));
CREATE TABLE "public"."auth_service_account"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),name text NOT NULL,status text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,UNIQUE(tenant_id,name));
CREATE TABLE "public"."auth_passkey"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),user_id bytea NOT NULL REFERENCES "public"."auth_user"(id),credential_id bytea NOT NULL UNIQUE,public_key bytea NOT NULL,sign_count bigint NOT NULL,transports text NOT NULL,aaguid bytea,backed_up boolean NOT NULL DEFAULT false,created_at bigint NOT NULL);
CREATE TABLE "public"."auth_webauthn_challenge"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),user_id bytea REFERENCES "public"."auth_user"(id),kind text NOT NULL,challenge bytea NOT NULL,expires_at bigint NOT NULL,consumed_at bigint,expected_password_hash text,ceremony text);
CREATE TABLE "public"."auth_mfa"(user_id bytea PRIMARY KEY REFERENCES "public"."auth_user"(id),totp_secret_crypt bytea NOT NULL,key_id text NOT NULL,enabled_at bigint NOT NULL);
CREATE TABLE "public"."auth_recovery_code"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),user_id bytea NOT NULL REFERENCES "public"."auth_user"(id),code_digest bytea NOT NULL,consumed_at bigint);
CREATE TABLE "public"."auth_permission"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),name text NOT NULL,UNIQUE(tenant_id,name));
CREATE TABLE "public"."auth_role"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),name text NOT NULL,UNIQUE(tenant_id,name));
CREATE TABLE "public"."auth_role_permission"(role_id bytea NOT NULL REFERENCES "public"."auth_role"(id),permission_id bytea NOT NULL REFERENCES "public"."auth_permission"(id),PRIMARY KEY(role_id,permission_id));
CREATE TABLE "public"."auth_membership"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),user_id bytea NOT NULL REFERENCES "public"."auth_user"(id),status text NOT NULL);
CREATE TABLE "public"."auth_membership_role"(membership_id bytea NOT NULL REFERENCES "public"."auth_membership"(id),role_id bytea NOT NULL REFERENCES "public"."auth_role"(id),PRIMARY KEY(membership_id,role_id));
CREATE TABLE "public"."auth_invitation"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),email text NOT NULL,token_digest bytea NOT NULL UNIQUE,expires_at bigint NOT NULL,accepted_at bigint);
CREATE TABLE "public"."auth_invitation_role"(invitation_id bytea NOT NULL REFERENCES "public"."auth_invitation"(id),role_id bytea NOT NULL REFERENCES "public"."auth_role"(id),PRIMARY KEY(invitation_id,role_id));
CREATE TABLE "public"."auth_audit"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea,actor_id bytea,action text NOT NULL,subject_kind text,subject_id bytea,outcome text NOT NULL,ip text,user_agent text,created_at bigint NOT NULL);
CREATE FUNCTION "public"."auth_audit_immutable"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only'; END $$;
CREATE TRIGGER "auth_audit_no_update_delete" BEFORE UPDATE OR DELETE ON "public"."auth_audit" FOR EACH ROW EXECUTE FUNCTION "public"."auth_audit_immutable"();
CREATE TABLE "public"."auth_group"(id bytea PRIMARY KEY CHECK(octet_length(id)=16), tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id), name text NOT NULL, created_at bigint NOT NULL, UNIQUE(tenant_id,name));
CREATE TABLE "public"."auth_group_member"(group_id bytea NOT NULL REFERENCES "public"."auth_group"(id), membership_id bytea NOT NULL REFERENCES "public"."auth_membership"(id), PRIMARY KEY(group_id,membership_id));
CREATE TABLE "public"."auth_social_state"(id bytea PRIMARY KEY CHECK(octet_length(id)=16),tenant_id bytea NOT NULL REFERENCES "public"."auth_tenant"(id),provider text NOT NULL,token_digest bytea NOT NULL UNIQUE,expires_at bigint NOT NULL,consumed_at bigint,created_at bigint NOT NULL);
CREATE TABLE "public"."auth_social_identity"(provider text NOT NULL,subject text NOT NULL,user_id bytea NOT NULL REFERENCES "public"."auth_user"(id),created_at bigint NOT NULL,PRIMARY KEY(provider,subject));
CREATE INDEX "auth_social_identity_user" ON "public"."auth_social_identity"(user_id);
